<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { planRequest } from '../api/client'
import PlanMonitor from './PlanMonitor.vue'
const data = ref<any>({ plans: {}, memories: [], needs: [], history: [] })
const level = ref('account'), target = ref('账户'), stage = ref('decision'), question = ref('')
const memoryKind = ref('intent'), memory = ref(''), source = ref(''), result = ref('')
const exported = ref<any>(null), preview = ref<any>(null), busy = ref(false), error = ref(''), message = ref('')
const notes = ref<Record<string, string>>({})
const levels: Record<string, string> = { account: '账户', direction: '行业方向', symbol: '具体标的' }
const fields: Record<string, string> = { thesis: '投资逻辑', stance: '当前立场', horizon: '投资期限', rationale: '判断依据', counter_evidence: '反证与不确定性', entry_condition: '进入 / 增持条件', exit_condition: '减持 / 退出条件', risk_budget: '风险与仓位边界', next_check: '下一检查点', review_on: '复查日期', confidence: '信心程度', confidence_reason: '信心依据', evidence_refs: '证据编号' }
const words: Record<string, string> = { research: '研究中', wait: '等待', hold: '持有', increase: '条件增持', reduce: '条件减持', exit: '退出', low: '低', medium: '中', high: '高', platform: '平台', external_model: '外部模型', user: '用户', open: '待补充', supplied: '材料已补充，待核验', blocked: '受阻', constraint: '投资约束', material: '原始资料', observation: '个人观察', intent: '投资意图', lesson: '经验教训' }
const scoped = (x: any) => x.level === level.value && x.target === target.value.trim()
const current = computed(() => data.value.plans[`${level.value}:${target.value.trim()}`])
const needs = computed(() => data.value.needs.filter(scoped))
const memories = computed(() => data.value.memories.filter((x: any) => scoped(x) || x.level === 'account'))
const history = computed(() => data.value.history.filter((x: any) => x.discussion && scoped(x.discussion)).slice().reverse())
const targets = computed(() => [...new Set([...Object.values(data.value.plans), ...data.value.needs, ...data.value.memories].filter((x: any) => x.level === level.value).map((x: any) => x.target))])
const display = (v: any) => Array.isArray(v) ? v.join('、') || '无' : words[v] || v || '未设置'
watch(level, v => { target.value = v === 'account' ? '账户' : ''; exported.value = null; preview.value = null })
watch([target, stage, question, result], () => { preview.value = null })
async function load() { data.value = await planRequest() }
async function run(fn: () => Promise<void>) { busy.value = true; error.value = ''; message.value = ''; try { await fn() } catch (e: any) { error.value = typeof e.response?.data?.detail === 'string' ? e.response.data.detail : '操作失败，请检查输入格式或重试' } finally { busy.value = false } }
onMounted(() => run(load))
async function addMemory() { await run(async () => { await planRequest('/memory', { level: level.value, target: target.value.trim(), kind: memoryKind.value, text: memory.value, source: source.value }); memory.value = ''; source.value = ''; exported.value = null; await load(); message.value = '补充已保存，后续讨论将携带此记忆' }) }
async function generate() { exported.value = null; await run(async () => { exported.value = await planRequest('/export', { level: level.value, target: target.value.trim(), stage: stage.value, question: question.value }); message.value = '请求包含账户敏感信息，仅在复制或下载后交给外部模型' }) }
async function copy() { await run(async () => { await navigator.clipboard.writeText(exported.value.prompt); message.value = '讨论提示词已复制' }) }
function download() { const url = URL.createObjectURL(new Blob([exported.value.prompt], { type: 'text/plain;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = `${exported.value.request_id}.txt`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
async function importResult(confirm = false) { await run(async () => { const r = await planRequest('/import', { result_json: result.value, confirm }); if (r.status === 'preview') preview.value = r; else { preview.value = null; result.value = ''; exported.value = null; await load(); message.value = '已确认保存，真实持仓未修改' } }) }
async function readFile(e: Event) { const f = (e.target as HTMLInputElement).files?.[0]; if (!f) return; if (f.size > 100000) { error.value = '文件超过100KB'; return } result.value = await f.text() }
async function updateNeed(n: any, status: string) { await run(async () => { await planRequest(`/needs/${n.id}`, { status, note: notes.value[n.id] || '' }); exported.value = null; await load() }) }
async function reviewMemory(id: string, status: string) { await run(async () => { await planRequest(`/memory/${id}`, { status }); exported.value = null; await load() }) }
async function discuss(value: { level: string; target: string; question: string }) {
  level.value = value.level
  await Promise.resolve()
  target.value = value.target; question.value = value.question; stage.value = 'decision'
}
</script>

<template>
  <section class="border-y border-border py-4 space-y-4 min-w-0 [overflow-wrap:anywhere]">
    <PlanMonitor @discuss="discuss" />
    <div class="flex flex-wrap items-center justify-between gap-3"><h3 class="font-semibold">投资计划与讨论</h3><div role="tablist" aria-label="投资层级" class="flex text-sm"><button v-for="(label, k) in levels" :key="k" role="tab" :aria-selected="level === k" :class="level === k ? 'bg-primary text-white' : 'text-muted-foreground'" class="px-3 py-2 rounded" @click="level = k">{{ label }}</button></div></div>
    <label v-if="level !== 'account'" class="block text-sm">{{ level === 'symbol' ? '标的代码（6位）' : '行业方向' }}<input v-model="target" list="plan-targets" class="block mt-1 w-full max-w-md rounded border border-border bg-background p-2" /><datalist id="plan-targets"><option v-for="t in targets" :key="String(t)" :value="String(t)" /></datalist></label>
    <div v-if="current" class="space-y-2 text-sm">
      <p class="font-semibold">{{ target }} · {{ display(current.content.stance) }} · 第{{ current.version }}版</p>
      <p>{{ current.content.thesis }}</p><p>下一检查：{{ current.content.next_check }} · {{ current.content.review_on }}</p>
      <p v-if="current.account_changed || current.review_due" class="text-warning">{{ current.account_changed ? '账户已变化，需重新讨论计划。' : '' }}{{ current.review_due ? '已到复查日期。' : '' }}</p>
      <details><summary class="text-sky-300 cursor-pointer">计划依据与执行条件</summary><dl class="grid gap-2 mt-2 sm:grid-cols-2"><div v-for="(label, k) in fields" :key="k"><dt class="text-muted-foreground">{{ label }}</dt><dd>{{ display(current.content[k]) }}</dd></div></dl></details>
    </div>
    <p v-else class="text-sm text-muted-foreground">尚无已确认计划。</p>
    <details v-if="needs.length" open class="text-sm"><summary class="cursor-pointer text-sky-300">研究清单 · {{ needs.length }}</summary><article v-for="n in needs" :key="n.id" class="py-3 border-b border-border space-y-1"><p class="font-medium">{{ n.question }}</p><p>{{ n.impact }}</p><p class="text-muted-foreground">所需来源：{{ n.source_needed }} · {{ display(n.owner) }} · {{ display(n.priority) }}优先级</p><p>{{ display(n.status) }} {{ n.note }}</p><p v-if="n.owner === 'platform' && n.status === 'open'" class="text-warning">本地巡检将执行已确认的取证工具；缺少工具或标的时会记录受阻原因。</p><textarea v-model="notes[n.id]" :aria-label="`${n.question}补充`" class="w-full border border-border bg-background rounded p-2" maxlength="6000" placeholder="来源、日期、材料，或受阻原因" /><div class="flex gap-3"><button :disabled="busy || !notes[n.id]?.trim()" class="text-sky-300 disabled:opacity-50" @click="updateNeed(n, 'supplied')">提交材料</button><button :disabled="busy || !notes[n.id]?.trim()" class="text-warning disabled:opacity-50" @click="updateNeed(n, 'blocked')">记录受阻</button></div></article></details>
    <details class="text-sm"><summary class="cursor-pointer text-sky-300">投资约束与补充记忆 · {{ memories.length }}</summary><div v-for="m in memories" :key="m.id" class="border-b border-border py-2"><p>{{ display(m.kind) }} · {{ m.status === 'candidate' ? '待验证候选' : '用户记录' }} · {{ m.at }}</p><p>{{ m.text }}</p><p class="text-muted-foreground">{{ m.source }}</p></div><div class="space-y-2 mt-3"><select v-model="memoryKind" aria-label="记忆类型" class="bg-background border border-border rounded p-2"><option v-for="k in ['constraint','material','observation','intent','lesson']" :key="k" :value="k">{{ words[k] }}</option></select><textarea v-model="memory" aria-label="补充记忆" maxlength="6000" class="block w-full bg-background border border-border rounded p-2" /><input v-model="source" aria-label="来源与适用范围" placeholder="来源、日期或适用范围" class="block w-full bg-background border border-border rounded p-2" /><button :disabled="busy || !target.trim() || !memory.trim()" class="px-3 py-2 border border-border rounded disabled:opacity-50" @click="addMemory">保存补充</button></div></details>
    <details class="text-sm" open><summary class="cursor-pointer font-medium">发起讨论 / 回传计划</summary><div class="mt-3 space-y-3"><select v-model="stage" aria-label="讨论阶段" class="bg-background border border-border rounded p-2"><option value="research">研究规划</option><option value="decision">决策讨论</option></select><textarea v-model="question" aria-label="讨论问题" maxlength="3000" placeholder="本次需要共同判断的问题" class="block w-full min-h-20 bg-background border border-border rounded p-2" /><div class="flex flex-wrap gap-3"><button :disabled="busy || !target.trim() || !question.trim()" class="bg-primary px-3 py-2 rounded disabled:opacity-50" @click="generate">{{ busy ? '处理中' : '生成讨论包' }}</button><button v-if="exported" :disabled="busy" class="text-sky-300" @click="copy">复制提示词</button><button v-if="exported" :disabled="busy" class="text-sky-300" @click="download">下载讨论包</button></div><p v-if="exported" class="text-xs text-muted-foreground">{{ exported.request_id }} · 有效至 {{ exported.expires_at }}</p><textarea v-model="result" aria-label="讨论结果 JSON" placeholder="外部模型返回的 JSON" class="block w-full min-h-20 bg-background border border-border rounded p-2 font-mono" /><input type="file" accept=".json,.txt" aria-label="导入讨论结果" class="max-w-full" @change="readFile" /><button :disabled="busy || !result.trim()" class="block border border-border px-3 py-2 rounded disabled:opacity-50" @click="importResult()">校验并预览草案</button></div></details>
    <div v-if="preview" class="space-y-3 text-sm border-l-2 border-sky-400 pl-3"><h4 class="font-semibold">待确认修改</h4><p>{{ preview.after.conclusion }}</p><div v-if="preview.after.plan" class="grid gap-3 sm:grid-cols-2"><div><h5 class="text-muted-foreground">原计划</h5><p v-if="!preview.before">未建立</p><p v-for="(label, k) in fields" v-else :key="k">{{ label }}：{{ display(preview.before.content[k]) }}</p></div><div><h5 class="text-sky-300">新计划草案</h5><p v-for="(label, k) in fields" :key="k">{{ label }}：{{ display(preview.after.plan[k]) }}</p></div></div><p v-for="n in preview.after.research" :key="n.question">研究：{{ n.question }} · {{ n.impact }} · {{ display(n.owner) }}</p><p v-for="l in preview.after.lesson_candidates" :key="l">教训候选（未验证）：{{ l }}</p><p class="text-warning">{{ preview.warning }}</p><button :disabled="busy" class="bg-primary px-3 py-2 rounded" @click="importResult(true)">确认保存计划与研究清单</button></div>
    <details v-if="history.length" class="text-sm"><summary class="text-sky-300 cursor-pointer">决策历史 · {{ history.length }}</summary><article v-for="h in history" :key="h.request_id" class="border-b border-border py-2"><p>{{ h.at }} · {{ h.discussion.question }}</p><p>{{ h.proposal.conclusion }}</p><details><summary class="cursor-pointer">当时计划与回传记录</summary><pre class="whitespace-pre-wrap break-all text-xs">{{ JSON.stringify({ before: h.before, after: h.proposal }, null, 2) }}</pre></details></article></details>
    <details v-if="memories.length" class="text-sm"><summary class="cursor-pointer text-sky-300">记忆审核与归档</summary><div v-for="m in memories" :key="m.id" class="border-b border-border py-2 space-y-2"><p>{{ m.text }} · {{ m.status === 'archived' ? '已归档，不用于新分析' : m.status === 'candidate' ? '待验证候选' : '用户确认' }}</p><div class="flex gap-3"><button v-if="m.status === 'candidate'" :disabled="busy" class="text-sky-300" @click="reviewMemory(m.id, 'user_confirmed')">确认为适用经验</button><button v-if="m.status !== 'archived'" :disabled="busy" class="text-muted-foreground" @click="reviewMemory(m.id, 'archived')">归档此记忆</button></div></div></details>
    <p v-if="preview" class="text-sm text-warning">待确认范围：{{ levels[preview.discussion.level] }} · {{ preview.discussion.target }}</p>
    <div v-if="preview?.after.research_answers?.length" class="text-sm space-y-2"><h4 class="font-semibold">待确认研究回答（原文引文已校验）</h4><article v-for="a in preview.after.research_answers" :key="a.need_id"><p>{{ a.conclusion }}</p><blockquote class="border-l-2 border-border pl-3">{{ a.quote }}</blockquote><p class="text-muted-foreground">{{ a.evidence_ref }} · 引文存在不代表判断正确</p></article></div>
    <details v-if="needs.some((n: any) => n.answer)" class="text-sm"><summary class="text-sky-300">已确认研究结论</summary><article v-for="n in needs.filter((n: any) => n.answer)" :key="n.id" class="py-2"><p>{{ n.question }}：{{ n.answer.conclusion }}</p><p>{{ n.answer.quote }}</p><a v-if="/^https:\/\//.test(n.answer.source_url || '')" :href="n.answer.source_url" target="_blank" rel="noopener noreferrer" class="text-sky-300">{{ n.answer.source_title }} · {{ n.answer.announced_at }}</a></article></details>
    <p v-if="error" role="alert" class="text-warning text-sm">{{ error }}</p><p v-if="message" role="status" class="text-sky-300 text-sm">{{ message }}</p>
    <details v-if="preview?.after.plan?.conditions?.length" class="text-sm" open><summary class="text-sky-300">待确认自动监控条件（{{ preview.after.plan.condition_mode === 'any' ? '任一满足' : '同时满足' }}）</summary><p v-for="(c, i) in preview.after.plan.conditions" :key="i">{{ c.label }} · {{ c.symbol }} · {{ c.metric }} {{ c.operator }} {{ c.threshold }} · {{ c.action }}</p></details>
    <details v-if="current?.content.conditions?.length" class="text-sm"><summary class="text-sky-300">已确认监控规则</summary><pre class="whitespace-pre-wrap break-all text-xs">{{ JSON.stringify(current.content.conditions, null, 2) }}</pre></details>
    <p v-if="current?.content.symbols?.length" class="text-sm">计划适用标的：{{ current.content.symbols.join('、') }}</p>
    <p v-if="preview?.after.plan?.symbols?.length" class="text-sm text-warning">待确认适用标的：{{ preview.after.plan.symbols.join('、') }}</p>
    <p class="text-xs text-muted-foreground">结构化规则由本地检查，复杂投资逻辑通过讨论核验，不自动执行交易。讨论包包含账户敏感信息。</p>
  </section>
</template>
